class Main {
    public static void main(String[] args) {
        // 입력한 점수로 조건을 판단해요.
        var scanner = new java.util.Scanner(System.in, "UTF-8");
        int score = scanner.nextInt();
        // 60도 합격에 포함하므로 >=를 써요.
        if (score >= 60) {
            System.out.println("합격");
        } else {
            System.out.println("재도전");
        }
    }
}
